custom_css:
/* --- 浸雨弦 Soaked Rain Strings 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影.--- */

/* --- 1. 字体导入矩阵 --- */
@import url('https://fonts.googleapis.com/css2?family=VT323&family=DotGothic16&display=swap');
@import url("https://fontsapi.zeoseven.com/7/main/result.css"); /* Zhuque Fangsong */
@import url("https://fontsapi.zeoseven.com/45/main/result.css"); /* nzgrRuYinZouZhangKai */
@import url("https://fontsapi.zeoseven.com/521/main/result.css"); /* JetBrains Maple Mono */
@import url("https://fontsapi.zeoseven.com/811/main/result.css"); /* ChangBanDianSong 16 SC */

/* --- 2. 核心颜色与样式变量 --- */
:root {
    --theme-bg: #030303;
    --panel-bg-color: rgba(10, 10, 10, 0.9);
    --panel-bg-hover: rgba(30, 30, 30, 0.95);
    --card-bg: rgba(15, 15, 15, 0.85);
    --input-bg: rgba(12, 12, 12, 0.9);
    --text-main: #f5f5f5;
    --text-subtle: #b0b0b0;
    --accent-white: #ffffff;
    --accent-grey: #6b6b6b;
    --accent-dark: #222222;
    --glitch-cyan: rgba(0, 255, 255, 0.4);
    --glitch-red: rgba(255, 0, 50, 0.4);

    --font-pixel-en: 'VT323', monospace;
    --font-pixel-jp: 'DotGothic16', monospace;
    --font-main: "Zhuque Fangsong (technical preview)", var(--font-pixel-jp), serif;
    --font-quote: "JetBrains Maple Mono", var(--font-pixel-jp), monospace;
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "ChangBanDianSong 16 SC", var(--font-pixel-jp), serif;
}

/* --- 3. 全局样式：无边框/阴影 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg) !important; 
    background-image: linear-gradient(rgba(5, 5, 5, 0.8), rgba(15, 15, 15, 0.9));
    background-size: cover; background-position: center; background-attachment: fixed;
    color: var(--text-main); font-family: var(--font-main); font-weight: normal; 
}

#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 200px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--accent-white); font-weight: normal; }

/* --- 4. 顶部导航栏 (修复覆盖问题) --- */
#top-settings-holder { position:relative; background-color: var(--panel-bg-color); backdrop-filter: blur(8px); border-bottom: 1px solid var(--accent-grey) !important; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.2s steps(3); image-rendering: pixelated; filter: grayscale(100%) contrast(1.2); }
.drawer-icon.fa-fw:hover { transform: translateY(-4px) scale(1.05); filter: grayscale(100%) brightness(1.5) drop-shadow(2px 0px 0px var(--glitch-red)) drop-shadow(-2px 0px 0px var(--glitch-cyan)); }

/* 导航栏图标强制精准替换 (使用ID) */
#ai-config-button .drawer-icon, #advanced-formatting-button .drawer-icon, #user-settings-button .drawer-icon, #extensions-settings-button .drawer-icon, #persona-management-button .drawer-icon, .fa-user, .fa-sliders, .fa-font, .fa-cubes, .fa-face-smile {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/ROWj/1960X1870/2026-04-27_154840.png/webp') !important; 
}
#sys-settings-button .drawer-icon, #WI-SP-button .drawer-icon, #bg_menu_button .drawer-icon, #table_database_settings_drawer .drawer-icon, #character_popup_button .drawer-icon, .fa-plug, .fa-book-atlas, .fa-image, .fa-panorama, .fa-bars-progress, .fa-address-card {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/bGtX/2280X2060/2026-04-27_154856.png/webp') !important; 
}

/* 抽屉与弹窗背景图替换 */
.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(5, 5, 5, 0.85), rgba(10, 10, 10, 0.95)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/uxCG/1200X675/8d55130e9139bc661f4080d5ec080238.jpg/webp') !important;
    background-size: cover; background-position: center; filter: grayscale(100%);
    border: 1px solid var(--accent-grey) !important; border-radius: 0;
}

/* --- 5. 底部悬浮输入栏 --- */
#send_textarea::placeholder { color: transparent !important; opacity: 0 !important; }
#form_sheld { position: absolute !important; bottom: 30px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; overflow: visible !important; }
#send_form { 
    pointer-events: auto; width: 80% !important; max-width: 800px !important; margin: 0 auto !important; 
    background-color: var(--input-bg) !important; padding: 12px 20px !important; 
    backdrop-filter: blur(10px) !important; position: relative; 
    border: 4px double var(--accent-grey) !important; 
    border-radius: 0 !important;
    animation: glitch-float 4s infinite alternate steps(5);
}
@keyframes glitch-float { 
    0% { transform: translateY(0); } 
    95% { transform: translateY(-4px); } 
    96% { transform: translateY(-4px) translateX(2px); }
    100% { transform: translateY(-5px); } 
}
#send_form:hover { background-color: var(--panel-bg-hover) !important; border-color: var(--accent-white) !important; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--accent-white) !important; font-family: var(--font-main); }

/* 左右黑白像素小翅膀 (已拉远距离防遮挡) */
#send_form::before {
    content: ''; position: absolute; left: -110px; top: -10px; width: 100px; height: 100px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/TegM/2252X2252/2026-04-27_093652.png/webp');
    background-size: contain; background-repeat: no-repeat; z-index: 50; pointer-events: none;
    filter: grayscale(100%) contrast(1.2);
    animation: wing-flap-left 2.5s infinite alternate steps(4);
}
#send_form::after {
    content: ''; position: absolute; right: -110px; top: -10px; width: 100px; height: 100px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/Q6J9/2252X2252/2026-04-27_093712.png/webp');
    background-size: contain; background-repeat: no-repeat; z-index: 50; pointer-events: none;
    filter: grayscale(100%) contrast(1.2);
    animation: wing-flap-right 2.5s infinite alternate steps(4);
}
@keyframes wing-flap-left { 0% { transform: translateY(0) rotate(-3deg); } 100% { transform: translateY(-6px) rotate(3deg); } }
@keyframes wing-flap-right { 0% { transform: translateY(0) rotate(3deg); } 100% { transform: translateY(-6px) rotate(-3deg); } }

/* 占位符文案 */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: '雨音が全てを消去する... [入力待機]'; 
    color: var(--text-subtle); position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); 
    font-family: var(--font-pixel-jp); font-size: clamp(12px, 2vw, 16px); pointer-events: none; z-index: 10; 
    white-space: nowrap; letter-spacing: 2px; 
    opacity: 0.6; animation: text-glitch 3s infinite steps(2);
}
@keyframes text-glitch { 0%, 90% { opacity: 0.6; text-shadow: none; } 95% { opacity: 1; text-shadow: 2px 0 var(--glitch-red), -2px 0 var(--glitch-cyan); } 100% { opacity: 0.2; } }

/* 底栏功能按钮贴图替换 */
#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button { width: 34px; height: 34px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.2s steps(2); font-size: 0; border: none; background-color: transparent; image-rendering: pixelated; margin: 0 4px; filter: grayscale(100%) contrast(1.5); }
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover { transform: translateY(-3px) scale(1.1); filter: grayscale(100%) brightness(2); }
#options_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/YNJm/2048X2048/2026-04-27_153655.png/webp'); }
#send_form #extensionsMenuButton, #auto_completion_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/8lfg/2048X2048/2026-04-27_153818.png/webp'); }
#send_but, #ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/Rd75/2048X2048/2026-04-27_153558.png/webp'); }

/* --- 6. 核心：消息卡片 --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; margin: 55px auto 140px !important; 
    width: 85%; max-width: 820px; 
    border: 1px solid var(--accent-dark) !important; border-radius: 0 !important;
    backdrop-filter: blur(5px) !important; overflow: visible !important; position: relative; 
}
.mes[is_user="false"] { background: var(--card-bg) !important; }
.mes[is_user="true"] { background: rgba(18, 18, 18, 0.85) !important; border-top: 1px solid var(--accent-grey) !important; }

/* 消息框顶部 GIF 背景替换 */
.mes .mesAvatarWrapper {
    display: flex; justify-content: center; align-items: center; padding: 0;
    width: 100%; height: 160px !important; min-height: 160px !important;
    background-size: cover; background-position: center; background-repeat: no-repeat;
    position: relative; z-index: 5; overflow: visible !important;
    border-bottom: 2px dashed var(--accent-grey);
    filter: grayscale(100%);
}
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/ix58/1024X512/81sH9qjL_converted.gif/webp'); }
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/Vugx/1024X512/dcVthPLD_converted.gif/webp'); }

/* ================= 新增：专属底部长方形承接框 ================= */
/* 所有消息统一的物理连接长方形 */
.mes::after {
    content: ''; position: absolute; 
    bottom: -25px; left: 50%; transform: translateX(-50%);
    width: 88%; height: 60px; 
    background-color: var(--panel-bg-color);
    border: 1px solid var(--accent-grey); border-top: none;
    z-index: 5; pointer-events: none;
}

/* AI消息框承接框：贴图放右边 */
.mes[is_user="false"]::before {
    content: ''; position: absolute; 
    bottom: -130px; right: -30px; left: auto; transform: none;
    width: 250px; height: 250px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/MpUv/2048X2048/2026-04-27_155223.png/webp');
    background-size: contain; background-position: right bottom; background-repeat: no-repeat;
    z-index: 20; pointer-events: none; filter: grayscale(100%) opacity(0.9);
}

/* User消息框承接框：贴图放中间 */
.mes[is_user="true"]::before {
    content: ''; position: absolute; 
    bottom: -130px; left: 50%; transform: translateX(-50%);
    width: 250px; height: 170px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/Woy5/2048X2048/2026-04-27_154229.png/webp');
    background-size: contain; background-position: center bottom; background-repeat: no-repeat;
    z-index: 20; pointer-events: none; filter: grayscale(100%) opacity(0.85);
}
/* ========================================================= */

/* 星星贴图：放入消息框的内部右下角 */
.mes .mes_block::before {
    content: ''; position: absolute; 
    bottom: 10px; right: 15px;
    width: 70px; height: 70px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/y2Uv/2048X2048/2026-04-27_153319.png/webp');
    background-size: contain; background-position: right bottom; background-repeat: no-repeat;
    z-index: 0; pointer-events: none; filter: grayscale(100%); opacity: 0.5;
}

/* 头像框与气泡字 */
.mes .avatar {
    position: absolute; top: 20px; width: 100px; height: 100px; 
    background: #000 !important; padding: 2px !important; 
    border: 1px solid var(--accent-grey) !important; 
    z-index: 30; display: flex !important; align-items: center; justify-content: center;
    border-radius: 0 !important; 
}
.mes[is_user="false"] .avatar { left: -30px; box-shadow: -4px 4px 0px rgba(85,85,85,0.3) !important; }
.mes[is_user="true"] .avatar { right: -30px; left: auto; box-shadow: 4px 4px 0px rgba(85,85,85,0.3) !important; }
.mes .avatar img { width: 100% !important; height: 100% !important; object-fit: cover !important; border-radius: 0 !important; border: none !important; filter: grayscale(100%) contrast(1.1); }

/* 气泡文字重设：符合故障与忧郁主题 */
.mes .avatar::after {
    position: absolute; bottom: -20px; right: -40px; padding: 2px 8px;
    font-family: var(--font-pixel-jp); font-size: 13px; font-weight: normal;
    white-space: nowrap; z-index: 40; letter-spacing: 1px;
}
.mes[is_user="false"] .avatar::after { content: 'ノイズ受信...'; background: #000; color: #fff; border: 1px solid #fff; right: -50px; }
.mes[is_user="true"] .avatar::after { content: '▶ 記憶の断片'; background: #fff; color: #000; border: 1px solid #000; left: -50px; right: auto; }

/* 文本区域 */
.mes .mes_block { background-color: transparent !important; background-image: none !important; padding: 25px 30px 40px 30px !important; position: relative; border: none !important; overflow: visible !important; min-height: 80px !important; z-index: 10; }
.mes .mes_text, .mes_reasoning { position: relative; z-index: 2; background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; }

/* --- 7. 思维链日系自定义与文字特效 --- */
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; backdrop-filter: none !important; padding: 0 !important; margin-bottom: 12px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { 
    content: "霙が降る... [思考のノイズを解析中]"; 
    font-family: var(--font-pixel-jp); font-size: 15px !important; 
    color: var(--accent-white); visibility: visible; letter-spacing: 2px; 
    text-shadow: 2px 0px 0px rgba(255,255,255,0.2);
}
.mes_reasoning { border-left: 2px dashed var(--accent-grey) !important; padding-left: 15px !important; margin-bottom: 20px !important; color: var(--text-subtle); font-family: var(--font-quote); font-size: 0.95em; }
.mes .mes_text { line-height: 1.8; color: var(--text-main); font-size: 16px; text-align: justify; }

/* 排版强化 */
.mes_text h1 { font-family: var(--font-title); color: var(--accent-white); font-size: 1.8em; text-align: center; position: relative; padding-bottom: 10px; margin: 25px 0 15px 0; border-bottom: 1px solid var(--accent-grey) !important; letter-spacing: 2px; }
.mes_text h1::before { content: '『 '; color: var(--text-subtle); } .mes_text h1::after { content: ' 』'; color: var(--text-subtle); }
.mes_text h2 { font-family: var(--font-title); color: var(--accent-white); font-size: 1.5em; padding: 4px 0 4px 15px; border-left: 4px solid var(--accent-grey) !important; margin: 20px 0 10px 0; background: linear-gradient(to right, rgba(255,255,255,0.05) 0%, transparent 100%); }
.mes_text em, .mes_text i { font-family: var(--font-quote); font-style: normal !important; color: var(--text-subtle); background: rgba(255,255,255,0.05); padding: 2px 4px; }
.mes_text strong, .mes_text b { font-family: var(--font-main); color: var(--accent-white); font-weight: bold; text-shadow: 1px 1px 0px var(--accent-grey); }
.mes_text blockquote { background-color: rgba(5, 5, 5, 0.8); border: 1px solid var(--accent-grey) !important; border-left: 4px solid #fff !important; padding: 12px 18px; margin: 15px 0; font-family: var(--font-quote); color: var(--quote_text_color); }
.mes_text span.quote, .mes_text q, .mes_text .dialogue { font-family: var(--font-quote); color: var(--quote_text_color); }
.mes_text code { font-family: var(--font-code) !important; background-color: #000 !important; color: var(--accent-white) !important; padding: 4px 8px; border: 1px dotted var(--accent-grey) !important; }

/* --- 8. 角色名外提与日系楼层 ID --- */
.mes .mesAvatarWrapper > .ch_name { display: none !important; }
.mes .mes_block > .ch_name { 
    display: flex !important; position: absolute; top: -180px !important; 
    width: auto !important; height: auto !important; background: #000 !important; 
    border: 1px solid var(--accent-white) !important; padding: 4px 12px !important; 
    z-index: 120; box-shadow: 4px 4px 0px rgba(255,255,255,0.1) !important; 
}
.mes[is_user="false"] .mes_block > .ch_name { left: 15px !important; right: auto !important; justify-content: flex-start !important; }
.mes[is_user="true"] .mes_block > .ch_name { right: 15px !important; left: auto !important; justify-content: flex-end !important; }
.mes .ch_name .name_text { font-family: var(--font-pixel-en) !important; font-size: 20px !important; color: var(--accent-white) !important; background: transparent !important; padding: 0 !important; border: none !important; line-height: 1; }

/* 楼层 ID 故障美化 */
.mes .mesIDDisplay {
    position: absolute; top: 165px !important; 
    background: transparent !important; border: none !important;
    color: var(--text-subtle) !important; font-size: 14px !important; z-index: 100; 
    padding: 0 !important; white-space: nowrap; line-height: 1 !important; 
    left: 50% !important; transform: translateX(-50%) !important; 
    font-family: var(--font-pixel-jp);
}
.mesIDDisplay::before { content: '【 残響記録 / '; color: var(--accent-grey); }
.mesIDDisplay::after { content: ' 消失 】'; color: var(--accent-grey); }
.mes .mes_timer { position: static !important; color: #666 !important; font-size: 12px !important; font-family: var(--font-pixel-en); background: transparent; padding: 0; border: none; }

/* --- 9. 编辑与互动按钮 (恢复原生FontAwesome显示) --- */
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 6px; position: static !important; opacity: 0.15; transition: opacity 0.3s ease; pointer-events: auto !important; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }

/* 解除所有的背景覆盖，还原ST原生DOM显示 */
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button {
    background-color: transparent !important; 
    color: var(--text-main) !important; /* 让原生图标足够亮 */
    font-size: 16px !important; /* 恢复图标大小 */
    height: 30px !important; width: 30px !important; 
    border: 1px dotted var(--accent-grey) !important; border-radius: 0 !important;
    background-image: none !important; /* 彻底清除旧图标影响 */
    transition: all 0.2s steps(2);
    display: inline-flex !important; align-items: center; justify-content: center;
}
.mes .mes_buttons .mes_button i, .mes .mes_edit_buttons .mes_button i, 
.mes .mes_buttons .mes_button::before, .mes .mes_edit_buttons .mes_button::before {
    display: inline-block !important;
    visibility: visible !important;
    opacity: 1 !important;
}
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { 
    background-color: var(--accent-white) !important; 
    color: #000 !important; 
    border-color: #fff !important;
    transform: scale(1.1) translateY(-2px);
    box-shadow: 2px 2px 0px var(--glitch-red), -2px -2px 0px var(--glitch-cyan) !important;
}


/* === 修复 mes_edit_buttons / mes_buttons 内 menu_button 的 FontAwesome 图标 ===
   全局 .menu_button 设置了 font-family: var(--font-pixel-jp)，会覆盖 FontAwesome
   导致 fa-check / fa-xmark / fa-pencil 等图标无法渲染，在此强制恢复 */
.mes_edit_buttons .menu_button,
.mes_buttons .menu_button {
    font-family: "Font Awesome 6 Free", "FontAwesome" !important;
    font-weight: 900 !important;
    -webkit-font-smoothing: antialiased !important;
    font-style: normal !important;
    font-variant: normal !important;
